pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address msgSender) public {
        vm.assume(msgSender != address(0));
        uint256 snapshot = vm.snapshot();
        vm.prank(msgSender);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        bool isOwner = msgSender == c.smartfix_owner();
        assertTrue(ok == isOwner);
        vm.revertTo(snapshot);
    }
}

